DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='vectora_app') THEN CREATE ROLE vectora_app LOGIN PASSWORD 'vectora_app'; END IF; END $$;
CREATE TABLE users(id BIGSERIAL PRIMARY KEY,username VARCHAR(60) UNIQUE NOT NULL,full_name VARCHAR(140) NOT NULL,role VARCHAR(40) NOT NULL,organization VARCHAR(100) NOT NULL,status VARCHAR(20) DEFAULT 'ACTIVE');
CREATE TABLE cameras(id BIGSERIAL PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,zone VARCHAR(80) NOT NULL,latitude NUMERIC(10,6) NOT NULL,longitude NUMERIC(10,6) NOT NULL,status VARCHAR(20) NOT NULL,firmware VARCHAR(30),last_seen TIMESTAMPTZ DEFAULT now());
CREATE TABLE sensors(id BIGSERIAL PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,sensor_type VARCHAR(40) NOT NULL,zone VARCHAR(80) NOT NULL,status VARCHAR(20) NOT NULL,range_meters INT NOT NULL,last_reading VARCHAR(80),last_seen TIMESTAMPTZ DEFAULT now());
CREATE TABLE drones(id BIGSERIAL PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,category VARCHAR(40) NOT NULL,operator_name VARCHAR(120),mission VARCHAR(140),latitude NUMERIC(10,6),longitude NUMERIC(10,6),altitude_m NUMERIC(8,2),speed_kmh NUMERIC(8,2),battery INT,status VARCHAR(24) NOT NULL,signal VARCHAR(20) NOT NULL,updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE missions(id BIGSERIAL PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(160) NOT NULL,mission_type VARCHAR(50) NOT NULL,area VARCHAR(100) NOT NULL,operator_name VARCHAR(120),drone_id BIGINT REFERENCES drones(id),start_at TIMESTAMPTZ NOT NULL,end_at TIMESTAMPTZ,status VARCHAR(24) NOT NULL,progress INT DEFAULT 0);
CREATE TABLE geofences(id BIGSERIAL PRIMARY KEY,name VARCHAR(140) NOT NULL,kind VARCHAR(30) NOT NULL,color VARCHAR(20) NOT NULL,points TEXT NOT NULL,status VARCHAR(20) NOT NULL);
CREATE TABLE events(id BIGSERIAL PRIMARY KEY,event_code VARCHAR(40) UNIQUE NOT NULL,event_type VARCHAR(40) NOT NULL,severity VARCHAR(20) NOT NULL,source_type VARCHAR(30) NOT NULL,source_code VARCHAR(40) NOT NULL,zone VARCHAR(80),message TEXT NOT NULL,status VARCHAR(24) NOT NULL,latitude NUMERIC(10,6),longitude NUMERIC(10,6),created_at TIMESTAMPTZ DEFAULT now(),acknowledged_by VARCHAR(100));
CREATE TABLE audit_events(id BIGSERIAL PRIMARY KEY,actor VARCHAR(100) NOT NULL,action VARCHAR(100) NOT NULL,resource VARCHAR(100) NOT NULL,details TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX idx_events_created ON events(created_at DESC); CREATE INDEX idx_drones_status ON drones(status); CREATE INDEX idx_cameras_zone ON cameras(zone);
